do $theory_insert$ declare x uuid:=public.cipmn_mock_seed_uuid('CIPMN-MOD-EL06:EXAM');j jsonb:=$theory$
[
{"position":26,"question":"Using only EL06, explain international development programme design from contextual analysis through sustainable results.","criteria":[{"name":"Needs","marks":2,"expected":"Needs assessment, baseline surveys and community consultations."},{"name":"Alignment","marks":2,"expected":"Sustainable Development Goals, national priorities and evidence-based planning."},{"name":"Results","marks":2,"expected":"Outputs, impact, logical frameworks and SMART indicators."},{"name":"Accountability","marks":2,"expected":"Transparency, reports, controls and audits."},{"name":"Adaptation","marks":2,"expected":"Local ownership, sustainability and adaptive management."}]},{"position":27,"question":"Using only EL06, compare Theory of Change and the Logical Framework for programme design and monitoring.","criteria":[{"name":"TOC","marks":2,"expected":"Theory of Change links activities, outcomes, impact, assumptions and conditions."},{"name":"Example","marks":2,"expected":"Midwife training to skilled attendance to safer delivery to reduced mortality."},{"name":"Hierarchy","marks":2,"expected":"Goal, Purpose/Outcome, Outputs and Activities."},{"name":"Measurement","marks":2,"expected":"Indicators, means of verification, assumptions and risks."},{"name":"Relationship","marks":2,"expected":"TOC is strategic narrative; LogFrame is measurable implementation plan."}]},{"position":28,"question":"Using only EL06, explain portfolio management in donor-funded and multicountry projects across culturally diverse settings.","criteria":[{"name":"Culture","marks":2,"expected":"Cultural traits, adapted leadership, local representatives and cultural risk."},{"name":"Governance","marks":2,"expected":"Donor compliance, local stakeholders, roles, decisions and feedback."},{"name":"Value","marks":2,"expected":"Indicators, inclusive communication, monitoring and collaboration."},{"name":"Learning","marks":2,"expected":"Feedback, actionable insights, adjustments and knowledge transfer."},{"name":"Portfolio","marks":2,"expected":"Strategic alignment, resource optimization and cohesive portfolio value."}]},{"position":29,"question":"Using only EL06, explain donor compliance, strategic partnership management and risk controls for sustainable programmes.","criteria":[{"name":"Compliance","marks":2,"expected":"Donor rules, ethics, financial procedures, audit checks and documentation."},{"name":"MoU","marks":2,"expected":"MoU commitments, reporting, deliverables, financial rules and monitoring."},{"name":"Coordination","marks":2,"expected":"Progress meetings, communication and feedback."},{"name":"Risk","marks":2,"expected":"Risk assessment, training, audits, conflict mechanisms and contingencies."},{"name":"Continuity","marks":2,"expected":"Compliance and partnership protect trust and continuity."}]},{"position":30,"question":"Using only EL06, develop a sustainability and exit approach including knowledge transfer and conflict management.","criteria":[{"name":"Ownership","marks":2,"expected":"Engage local stakeholders and build local ownership."},{"name":"Capacity","marks":2,"expected":"Training, mentoring, technical support and manageable tools."},{"name":"Exit","marks":2,"expected":"Measurable exit criteria, monitoring and transition adjustment."},{"name":"Knowledge","marks":2,"expected":"Knowledge transfer through workshops, webinars and peer learning."},{"name":"Conflict","marks":2,"expected":"Conflict resolution through respect, cultural awareness, mediation and early procedures."}]}
]
$theory$::jsonb;q jsonb;qid uuid;begin for q in select value from jsonb_array_elements(j)loop qid:=public.cipmn_mock_seed_uuid('CIPMN-MOD-EL06:THEORY:'||((q->>'position')::int-25));insert into public.questions(id,examination_id,question_text,question_type,section,position,points,is_active)values(qid,x,q->>'question','theory','theory',(q->>'position')::int,10,true);insert into public.theory_marking_rubrics(question_id,max_score,rubric,source_label,is_active)values(qid,10,jsonb_build_object('criteria',q->'criteria'),'CIPMN-MOD-012.pptx (39 slides/pages; treated as EL06; reviewed 2026-09-26)',true);end loop;end $theory_insert$;
